import{_ as a,o as t,c as r,a0 as i}from"./chunks/framework.BPYRhTv9.js";const p=JSON.parse('{"title":"Limitations","description":"","frontmatter":{"title":"Limitations"},"headers":[],"relativePath":"reference/limitations.md","filePath":"reference/limitations.md"}'),s={name:"reference/limitations.md"};function o(n,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h1><p><em>Last updated: Jul 17, 2026</em></p><p>These are constraints we chose on purpose. They are not bugs — they are product decisions listed here so you understand what we have prioritized.</p><h3 id="no-user-accounts" tabindex="-1">No user accounts <a class="header-anchor" href="#no-user-accounts" aria-label="Permalink to &quot;No user accounts&quot;">​</a></h3><p>Wibe Stories does not require a login or sign-up. You open the page and start creating cards immediately — no email, no password, no account to create.</p><ul><li>Your cards, settings, and preferences are tied to the browser you are using. They do not follow you across devices.</li><li>Clearing browser data removes everything associated with that session.</li><li>A Pro key is the way to access your stored cards from any browser. As long as you have the key, your cards are available on any device.</li></ul><p><strong>Why no accounts?</strong></p><p>User accounts would require a server-side identity layer — authentication, password management, email verification, session tokens — that does not align with the current scope of the app. The Pro key system solves the one case where cross-device access matters without a full account system.</p><p>We may revisit this decision in the future, but have no concrete plans to build a full account system.</p><h3 id="daily-caps-keep-the-service-sustainable" tabindex="-1">Daily caps keep the service sustainable <a class="header-anchor" href="#daily-caps-keep-the-service-sustainable" aria-label="Permalink to &quot;Daily caps keep the service sustainable&quot;">​</a></h3><p>Free tier: 5 recordings per day, 1 tone rewrite per tone per day, 15-second max recording length. Pro raises recordings to 50 per day and makes rewrites unlimited.</p><ul><li><strong>Sustainability:</strong> Speech-to-text and tone rewrite costs both scale with usage. Caps keep infrastructure bills predictable.</li><li><strong>Abuse prevention:</strong> Scripts that create large numbers of cards per minute or scrape rewritten phrases are blocked by daily limits.</li><li><strong>Pro accounts</strong> provide a verified payment method that can be revoked if abuse is detected.</li><li>The recording counter changes color as you approach the limit, and recordings are blocked once you reach it.</li></ul><h3 id="the-free-tier-has-a-shared-daily-capacity-pool" tabindex="-1">The free tier has a shared daily capacity pool <a class="header-anchor" href="#the-free-tier-has-a-shared-daily-capacity-pool" aria-label="Permalink to &quot;The free tier has a shared daily capacity pool&quot;">​</a></h3><p>Free users share a daily capacity pool. When the pool is reached, new users see a full-screen overlay; users already active are not affected.</p><ul><li>This caps the maximum daily infrastructure cost, not individual usage.</li><li>Pro users bypass this cap entirely.</li><li>The cap resets daily.</li></ul><h3 id="recordings-are-15-seconds-free-or-30-seconds-pro" tabindex="-1">Recordings are 15 seconds (free) or 30 seconds (Pro) <a class="header-anchor" href="#recordings-are-15-seconds-free-or-30-seconds-pro" aria-label="Permalink to &quot;Recordings are 15 seconds (free) or 30 seconds (Pro)&quot;">​</a></h3><p>The limit is driven by speech-to-text costs.</p><ul><li>15 seconds captures one complete thought. Longer recordings tend to contain multiple thoughts or silence.</li><li>The recording toolbar shows a live countdown timer with the last seconds highlighted in red.</li><li>Uploaded WAV or MP3 files run through the same transcription engine with the same length limits. Accuracy depends on file quality, background noise, and accent. Edit the text box or tap reset to try again.</li></ul><h3 id="card-text-is-capped-at-150-characters" tabindex="-1">Card text is capped at 150 characters <a class="header-anchor" href="#card-text-is-capped-at-150-characters" aria-label="Permalink to &quot;Card text is capped at 150 characters&quot;">​</a></h3><p>Shorter messages make better-looking, more shareable cards.</p><ul><li>150 characters fits a thoughtful sentence without overflowing the card canvas. Most example phrases fit comfortably.</li><li>The counter turns red and the Done button disables past 150, but the text area does not block input — you can see what you would lose by shortening.</li><li>An invisible grace zone of a few extra characters prevents cutting a final word mid-letter. The card image, transcription, and tone rewriting all use the first 150 characters.</li></ul><h3 id="shared-links-expire-after-7-days-14-for-pro" tabindex="-1">Shared links expire after 7 days (14 for Pro) <a class="header-anchor" href="#shared-links-expire-after-7-days-14-for-pro" aria-label="Permalink to &quot;Shared links expire after 7 days (14 for Pro)&quot;">​</a></h3><p>A cleanup process runs daily to remove expired card data.</p><ul><li><strong>Deleted:</strong> card image, voice recording, and associated metadata.</li><li><strong>Preserved:</strong> Downloaded images are yours forever. Cards saved to the vault are exempt from cleanup.</li></ul><h3 id="we-do-not-run-automated-content-moderation" tabindex="-1">We do not run automated content moderation <a class="header-anchor" href="#we-do-not-run-automated-content-moderation" aria-label="Permalink to &quot;We do not run automated content moderation&quot;">​</a></h3><p>No automated filter exists for card text or voice recordings.</p><ul><li>Daily caps make bulk automated abuse impractical.</li><li>A determined user can create any content. A reporting mechanism is planned but not yet implemented.</li></ul><h3 id="cards-are-available-in-one-size-only" tabindex="-1">Cards are available in one size only <a class="header-anchor" href="#cards-are-available-in-one-size-only" aria-label="Permalink to &quot;Cards are available in one size only&quot;">​</a></h3><p>We previously offered four sizes (1:1, 9:16, 4:5, 16:9). On mobile, the wider sizes got cropped, the background illustration was cut off, and social media previews were inconsistent. After testing across multiple devices, only the square works reliably on every screen.</p><ul><li>This is a deliberate product decision, not a missing feature.</li></ul><h3 id="vault-storage-is-capped-at-50-cards-for-pro-users" tabindex="-1">Vault storage is capped at 50 cards for Pro users <a class="header-anchor" href="#vault-storage-is-capped-at-50-cards-for-pro-users" aria-label="Permalink to &quot;Vault storage is capped at 50 cards for Pro users&quot;">​</a></h3><p>Pro vault cards are stored on the server and persist across sessions. The 50-card limit protects against bulk abuse.</p><ul><li>Free users&#39; vault data stays in the browser — no cap, but data is lost on browser data clear.</li><li>The vault shows a count badge to make the limit visible. Select and delete to stay under the cap.</li></ul><h3 id="audio-uploads-are-limited-in-size-and-format" tabindex="-1">Audio uploads are limited in size and format <a class="header-anchor" href="#audio-uploads-are-limited-in-size-and-format" aria-label="Permalink to &quot;Audio uploads are limited in size and format&quot;">​</a></h3><p>Uploaded audio files are validated before processing.</p><ul><li>Accepted formats: WAV and MP3.</li><li>Files that exceed the size limit are rejected with a clear message.</li></ul><h3 id="older-safari-versions-may-show-slightly-different-layouts" tabindex="-1">Older Safari versions may show slightly different layouts <a class="header-anchor" href="#older-safari-versions-may-show-slightly-different-layouts" aria-label="Permalink to &quot;Older Safari versions may show slightly different layouts&quot;">​</a></h3><p>Older Safari versions may show tighter spacing and slightly different card aspect ratios — graceful degradations, not bugs.</p><hr>',39)])])}const m=a(s,[["render",o]]);export{p as __pageData,m as default};
